1	import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
2	import { existsSync, readFileSync, statSync } from "node:fs";
3	import { extname, resolve, sep } from "node:path";
4	import { timingSafeEqual } from "node:crypto";
5	import { verifyProof, type SemaphoreProof } from "@semaphore-protocol/proof";
6	import { openCatalog, STATUSES, type AuditQuery, type GroupOperation, type NewPollInput } from "./store.ts";
7	import { isCommitment, isProofPayload, terminateProverWorkers, textToField } from "./voting.ts";
8	import type { AuditEvent, PollStatus } from "./types.ts";
9	
10	const MAX_BODY_BYTES = 1_000_000;
11	
12	export interface AppOptions {
13	  /** When unset (or empty) every administrative request is refused with 401. */
14	  adminToken?: string;
15	}
16	
17	function readBody(request: IncomingMessage): Promise<string> {
18	  return new Promise((resolvePromise, rejectPromise) => {
19	    const chunks: Buffer[] = [];
20	    let size = 0;
21	    request.on("data", (chunk: Buffer) => {
22	      size += chunk.length;
23	      if (size > MAX_BODY_BYTES) { rejectPromise(new Error("body_too_large")); request.destroy(); return; }
24	      chunks.push(chunk);
25	    });
26	    request.on("end", () => resolvePromise(Buffer.concat(chunks).toString("utf8")));
27	    request.on("error", rejectPromise);
28	  });
29	}
30	
31	function isNonEmptyString(value: unknown, maxLength = 2000): value is string {
32	  return typeof value === "string" && value.trim().length > 0 && value.length <= maxLength;
33	}
34	function isIsoDate(value: unknown): value is string {
35	  return typeof value === "string" && Number.isFinite(Date.parse(value));
36	}
37	
38	export function createApp(databasePath: string, publicPath = resolve("dist/public"), options: AppOptions = {}) {
39	  const catalog = openCatalog(databasePath);
40	  const adminToken = options.adminToken && options.adminToken.length > 0 ? options.adminToken : undefined;
41	  let proverUsed = false;
42	  const mime: Record<string, string> = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8", ".svg": "image/svg+xml", ".json": "application/json; charset=utf-8" };
43	  const server = createServer((request, response) => {
44	    handle(request, response).catch(() => {
45	      if (!response.headersSent) response.writeHead(500, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
46	      response.end(JSON.stringify({ error: "internal_error" }));
47	    });
48	  });
49	  server.on("close", () => {
50	    catalog.close();
51	    // Release the snarkjs worker pool so the process can exit.
52	    if (proverUsed) void terminateProverWorkers();
53	  });
54	  return server;
55	
56	  /**
57	   * Authorization gate for management endpoints. A missing, wrong or
58	   * unconfigured token is refused with 401 admin_unauthorized. The check
59	   * runs before the body is read and never mutates data or writes audit.
60	   */
61	  function isAuthorized(request: IncomingMessage): boolean {
62	    if (!adminToken) return false;
63	    const provided = request.headers["x-admin-token"];
64	    if (typeof provided !== "string") return false;
65	    const expected = Buffer.from(adminToken);
66	    const actual = Buffer.from(provided);
67	    return expected.length === actual.length && timingSafeEqual(expected, actual);
68	  }
69	
70	  async function handle(request: IncomingMessage, response: ServerResponse) {
71	    function json(status: number, payload: unknown, headers: Record<string, string> = {}) {
72	      response.writeHead(status, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", ...headers });
73	      response.end(JSON.stringify(payload));
74	    }
75	    function requireAdmin(): boolean {
76	      if (isAuthorized(request)) return true;
77	      json(401, { error: "admin_unauthorized" });
78	      return false;
79	    }
80	    const url = new URL(request.url ?? "/", "http://localhost");
81	    const segments = url.pathname.split("/").filter(Boolean);
82	    if (segments[0] === "api") {
83	      const method = request.method ?? "GET";
84	      if (url.pathname === "/api/health") {
85	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
86	        return json(200, { service: "veilvote", status: "ok" });
87	      }
88	      if (segments[1] === "admin" && segments[2] === "audit" && segments.length === 3) {
89	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
90	        if (!requireAdmin()) return;
91	        const query = parseAuditQuery(url.searchParams);
92	        if (!query.ok) return json(400, { error: query.error });
93	        return json(200, catalog.auditQuery(query.query));
94	      }
95	      if (segments[1] === "polls" && segments.length <= 4) {
96	        if (segments.length === 2) {
97	          // Public catalog list; creating a poll is admin-only and starts in draft.
98	          if (method === "GET") return json(200, { polls: catalog.list(Date.now(), isAuthorized(request)) });
99	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "GET, POST" });
100	          if (!requireAdmin()) return;
101	          let body: unknown;
102	          try { body = JSON.parse(await readBody(request)); }
103	          catch {
104	            catalog.auditFailure("poll_create", "unknown", { reason: "invalid_json" });
105	            return json(400, { error: "invalid_json" });
106	          }
107	          const parsed = parseNewPoll(body);
108	          if (!parsed.ok) {
109	            catalog.auditFailure("poll_create", parsed.pollId, { reason: parsed.reason });
110	            return json(400, { error: parsed.reason });
111	          }
112	          const outcome = catalog.createPoll(parsed.input);
113	          if (!outcome.ok) {
114	            catalog.auditFailure("poll_create", parsed.input.id, { reason: "poll_exists" });
115	            return json(409, { error: "poll_exists" });
116	          }
117	          return json(201, { poll: outcome.poll });
118	        }
119	        let id: string;
120	        try { id = decodeURIComponent(segments[2]); }
121	        catch { return json(400, { error: "invalid_poll_id" }); }
122	        if (segments.length === 3) {
123	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
124	          const poll = catalog.get(id);
125	          // Drafts are invisible to ordinary detail requests; an authorized
126	          // manager can still read them to prepare the opening.
127	          if (!poll || (poll.status === "draft" && !isAuthorized(request))) return json(404, { error: "poll_not_found" });
128	          return json(200, { poll });
129	        }
130	        if (segments[3] === "results") {
131	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
132	          const result = catalog.results(id);
133	          return result ? json(200, { result }) : json(404, { error: "poll_not_found" });
134	        }
135	        if (segments[3] === "status") {
136	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
137	          if (!requireAdmin()) return;
138	          let body: unknown;
139	          try { body = JSON.parse(await readBody(request)); }
140	          catch {
141	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_json" });
142	            return json(400, { error: "invalid_json" });
143	          }
144	          if (typeof body !== "object" || body === null) {
145	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_status" });
146	            return json(400, { error: "invalid_status" });
147	          }
148	          const { status, expectedStatus } = body as { status?: unknown; expectedStatus?: unknown };
149	          if (!isStatus(status) || !isStatus(expectedStatus)) {
150	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_status", requested: String(status), expected: String(expectedStatus) });
151	            return json(400, { error: "invalid_status" });
152	          }
153	          const outcome = catalog.transitionStatus(id, status, expectedStatus);
154	          if (!outcome.ok) {
155	            if (outcome.reason === "poll_missing") return json(404, { error: "poll_not_found" });
156	            if (outcome.reason === "invalid_status") return json(400, { error: "invalid_status" });
157	            return json(409, { error: outcome.reason });
158	          }
159	          const poll = catalog.get(id);
160	          return json(200, { status: outcome.status, poll });
161	        }
162	        if (segments[3] === "group") {
163	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
164	          if (!requireAdmin()) return;
165	          let body: unknown;
166	          try { body = JSON.parse(await readBody(request)); }
167	          catch {
168	            catalog.auditFailure("group_change_rejected", id, { reason: "invalid_json" });
169	            return json(400, { error: "invalid_json" });
170	          }
171	          if (typeof body !== "object" || body === null) {
172	            catalog.auditFailure("group_change_rejected", id, { reason: "invalid_group_operation" });
173	            return json(400, { error: "invalid_group_operation" });
174	          }
175	          const { operation, expectedVersion, commitment, oldCommitment, newCommitment } = body as Record<string, unknown>;
176	          if (!Number.isInteger(expectedVersion) || (expectedVersion as number) < 1) {
177	            catalog.auditFailure("group_change_rejected", id, { operation: String(operation), reason: "invalid_group_operation" });
178	            return json(400, { error: "invalid_group_operation" });
179	          }
180	          let groupOperation: GroupOperation;
181	          if (operation === "join" && isCommitment(commitment)) groupOperation = { type: "join", commitment };
182	          else if (operation === "rotate" && isCommitment(oldCommitment) && isCommitment(newCommitment)) groupOperation = { type: "rotate", oldCommitment, newCommitment };
183	          else if (operation === "revoke" && isCommitment(commitment)) groupOperation = { type: "revoke", commitment };
184	          else {
185	            catalog.auditFailure("group_change_rejected", id, { operation: String(operation), reason: "invalid_group_operation" });
186	            return json(400, { error: "invalid_group_operation" });
187	          }
188	          const outcome = catalog.applyGroupOperation(id, groupOperation, expectedVersion as number);
189	          if (!outcome.ok) {
190	            if (outcome.reason === "poll_missing") return json(404, { error: "poll_not_found" });
191	            if (outcome.reason === "group_frozen" || outcome.reason === "group_version_changed" || outcome.reason === "poll_not_editable") return json(409, { error: outcome.reason });
192	            return json(400, { error: outcome.reason });
193	          }
194	          return json(201, { group: outcome.group });
195	        }
196	        if (segments[3] === "votes") {
197	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
198	          const poll = catalog.get(id);
199	          // Drafts are invisible to the public (404), matching detail/results.
200	          if (!poll || poll.status === "draft") return json(404, { error: "poll_not_found" });
201	          let body: unknown;
202	          try { body = JSON.parse(await readBody(request)); }
203	          catch { return json(400, { error: "invalid_json" }); }
204	          if (typeof body !== "object" || body === null) return json(400, { error: "invalid_vote" });
205	          const { optionId, proof, groupVersion } = body as { optionId?: unknown; proof?: unknown; groupVersion?: unknown };
206	          if (typeof optionId !== "string" || optionId.length === 0 || !isProofPayload(proof)) {
207	            return json(400, { error: "invalid_vote" });
208	          }
209	          if (groupVersion !== undefined && (!Number.isInteger(groupVersion) || (groupVersion as number) < 1)) {
210	            return json(400, { error: "invalid_vote" });
211	          }
212	          if (!poll.options.some(option => option.id === optionId)) return json(400, { error: "unknown_option" });
213	          // Only open polls before their deadline accept votes. Drafts and
214	          // closed/archived polls answer poll_closed; results stay public.
215	          if (poll.status !== "open" || Date.now() >= Date.parse(poll.closesAt)) return json(409, { error: "poll_closed" });
216	          // Resolve the immutable snapshot the proof must bind to: either the
217	          // explicitly requested version, or the version whose Merkle root the
218	          // proof carries (legacy clients that omit groupVersion). Historical
219	          // versions conflict; unknown roots are unprocessable.
220	          let snapshotVersion: number;
221	          if (groupVersion !== undefined) {
222	            if (groupVersion !== poll.groupVersion) return json(409, { error: "group_version_changed" });
223	            if (proof.merkleTreeRoot !== poll.merkleRoot) return json(422, { error: "proof_binding_mismatch" });
224	            snapshotVersion = groupVersion as number;
225	          } else {
226	            const snapshot = catalog.groupSnapshotByRoot(poll.id, proof.merkleTreeRoot);
227	            if (!snapshot) return json(422, { error: "unknown_merkle_root" });
228	            if (snapshot.version !== poll.groupVersion) return json(409, { error: "group_version_changed" });
229	            snapshotVersion = snapshot.version;
230	          }
231	          // The proof must also be bound to this poll (scope) and the chosen
232	          // option (message).
233	          let bound = false;
234	          try {
235	            bound = proof.scope === textToField(poll.id) && proof.message === textToField(optionId);
236	          } catch { bound = false; }
237	          if (!bound) return json(422, { error: "proof_binding_mismatch" });
238	          let valid = false;
239	          proverUsed = true;
240	          try { valid = await verifyProof(proof as unknown as SemaphoreProof); }
241	          catch { valid = false; }
242	          if (!valid) return json(422, { error: "invalid_proof" });
243	          // Snapshot confirmation, freeze-on-first-vote, nullifier dedup and
244	          // the vote write commit atomically; a concurrent group change makes
245	          // exactly one of the two succeed. A vote racing closesAt is rejected
246	          // as the poll is persisted closed in that same transaction.
247	          const outcome = catalog.commitVote(poll.id, optionId, proof.nullifier, snapshotVersion);
248	          if (!outcome.ok) {
249	            if (outcome.reason === "duplicate_nullifier") return json(409, { error: "duplicate_nullifier" });
250	            if (outcome.reason === "group_version_changed") return json(409, { error: "group_version_changed" });
251	            if (outcome.reason === "poll_closed") return json(409, { error: "poll_closed" });
252	            return json(400, { error: "unknown_option" });
253	          }
254	          return json(201, { receipt: outcome.receipt });
255	        }
256	      }
257	      if (segments[1] === "receipts" && segments.length === 3) {
258	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
259	        let id: string;
260	        try { id = decodeURIComponent(segments[2]); }
261	        catch { return json(400, { error: "invalid_receipt_id" }); }
262	        const receipt = catalog.receipt(id);
263	        return receipt ? json(200, { receipt }) : json(404, { error: "receipt_not_found" });
264	      }
265	      if (segments[1] === "receipts" && segments.length === 4 && segments[3] === "verify") {
266	        // A voter proves their ballot was counted by presenting the receipt's
267	        // own public fields; nothing here links the receipt to an identity.
268	        if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
269	        let id: string;
270	        try { id = decodeURIComponent(segments[2]); }
271	        catch { return json(400, { error: "invalid_receipt_id" }); }
272	        let body: unknown;
273	        try { body = JSON.parse(await readBody(request)); }
274	        catch { return json(400, { error: "invalid_json" }); }
275	        if (typeof body !== "object" || body === null) return json(400, { error: "invalid_verification" });
276	        const { pollId, optionId, nullifier } = body as Record<string, unknown>;
277	        if (typeof pollId !== "string" || typeof optionId !== "string" || typeof nullifier !== "string") {
278	          return json(400, { error: "invalid_verification" });
279	        }
280	        const receipt = catalog.receipt(id);
281	        if (!receipt) return json(404, { error: "receipt_not_found" });
282	        if (receipt.pollId !== pollId || receipt.optionId !== optionId || receipt.nullifier !== nullifier) {
283	          return json(422, { error: "receipt_mismatch" });
284	        }
285	        return json(200, { valid: true, receipt });
286	      }
287	      return json(404, { error: "not_found" });
288	    }
289	    if (request.method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
290	    let relativePath: string;
291	    try { relativePath = decodeURIComponent(url.pathname); }
292	    catch { return json(400, { error: "invalid_path" }); }
293	    const file = resolve(publicPath, relativePath === "/" ? "index.html" : `.${relativePath}`);
294	    if (!file.startsWith(`${resolve(publicPath)}${sep}`) || !existsSync(file) || !statSync(file).isFile()) return json(404, { error: "not_found" });
295	    response.writeHead(200, { "Content-Type": mime[extname(file)] ?? "application/octet-stream", "X-Content-Type-Options": "nosniff" });
296	    response.end(readFileSync(file));
297	  }
298	}
299	
300	function isStatus(value: unknown): value is PollStatus {
301	  return typeof value === "string" && (STATUSES as readonly string[]).includes(value);
302	}
303	
304	const DEFAULT_AUDIT_PAGE_SIZE = 50;
305	const MAX_AUDIT_PAGE_SIZE = 200;
306	
307	type ParseAuditQueryResult =
308	  | { ok: true; query: AuditQuery }
309	  | { ok: false; error: string };
310	
311	/**
312	 * Validates the audit trail filters. from/to must be ISO8601 instants and are
313	 * inclusive at both ends; an unparseable value or an inverted range is a 400.
314	 * pageSize defaults to 50 and is capped at 200.
315	 */
316	function parseAuditQuery(params: URLSearchParams): ParseAuditQueryResult {
317	  const query: AuditQuery = { page: 1, pageSize: DEFAULT_AUDIT_PAGE_SIZE };
318	  const from = params.get("from");
319	  const to = params.get("to");
320	  if (from !== null) {
321	    if (!isIsoDate(from)) return { ok: false, error: "invalid_time_range" };
322	    query.from = new Date(Date.parse(from)).toISOString();
323	  }
324	  if (to !== null) {
325	    if (!isIsoDate(to)) return { ok: false, error: "invalid_time_range" };
326	    query.to = new Date(Date.parse(to)).toISOString();
327	  }
328	  if (query.from !== undefined && query.to !== undefined && query.from > query.to) {
329	    return { ok: false, error: "invalid_time_range" };
330	  }
331	  const pollId = params.get("pollId");
332	  if (pollId !== null) query.pollId = pollId;
333	  const action = params.get("action");
334	  if (action !== null) query.action = action;
335	  const result = params.get("result");
336	  if (result !== null) query.result = result;
337	  const page = params.get("page");
338	  if (page !== null) {
339	    const parsed = Number(page);
340	    if (!Number.isInteger(parsed) || parsed < 1) return { ok: false, error: "invalid_pagination" };
341	    query.page = parsed;
342	  }
343	  const pageSize = params.get("pageSize");
344	  if (pageSize !== null) {
345	    const parsed = Number(pageSize);
346	    if (!Number.isInteger(parsed) || parsed < 1) return { ok: false, error: "invalid_pagination" };
347	    query.pageSize = Math.min(parsed, MAX_AUDIT_PAGE_SIZE);
348	  }
349	  return { ok: true, query };
350	}
351	
352	type ParsePollResult =
353	  | { ok: true; input: NewPollInput }
354	  | { ok: false; reason: string; pollId: string };
355	
356	/**
357	 * Validates a draft creation payload: all existing poll fields, a non-empty
358	 * list of distinct member commitments and at least two options with unique
359	 * ids. Returns a machine-readable error code on failure.
360	 */
361	function parseNewPoll(body: unknown): ParsePollResult {
362	  if (typeof body !== "object" || body === null) return { ok: false, reason: "invalid_poll", pollId: "unknown" };
363	  const b = body as Record<string, unknown>;
364	  const pollId = typeof b.id === "string" && b.id.trim() ? b.id : "unknown";
365	  const fail = (reason: string): ParsePollResult => ({ ok: false, reason, pollId });
366	  if (!isNonEmptyString(b.id, 128)) return fail("invalid_poll_id");
367	  if (!isNonEmptyString(b.title)) return fail("invalid_poll");
368	  if (!isNonEmptyString(b.summary)) return fail("invalid_poll");
369	  if (!isNonEmptyString(b.description, 20_000)) return fail("invalid_poll");
370	  if (!isNonEmptyString(b.organizer)) return fail("invalid_poll");
371	  if (!isIsoDate(b.publishedAt) || !isIsoDate(b.closesAt)) return fail("invalid_poll_dates");
372	  if (Date.parse(b.closesAt as string) <= Date.parse(b.publishedAt as string)) return fail("invalid_poll_dates");
373	  if (!Array.isArray(b.options) || b.options.length < 2) return fail("invalid_options");
374	  const optionIds = new Set<string>();
375	  const options: { id: string; label: string }[] = [];
376	  for (const option of b.options) {
377	    if (typeof option !== "object" || option === null) return fail("invalid_options");
378	    const { id, label } = option as { id?: unknown; label?: unknown };
379	    if (!isNonEmptyString(id, 128) || !isNonEmptyString(label)) return fail("invalid_options");
380	    if (optionIds.has(id)) return fail("duplicate_option_id");
381	    optionIds.add(id);
382	    options.push({ id, label });
383	  }
