90	      id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL,
91	      description TEXT NOT NULL, organizer TEXT NOT NULL, status TEXT NOT NULL,
92	      published_at TEXT NOT NULL, closes_at TEXT NOT NULL, options_json TEXT NOT NULL
93	    );
94	    CREATE TABLE IF NOT EXISTS members (
95	      commitment TEXT PRIMARY KEY, position INTEGER NOT NULL UNIQUE
96	    );
97	    CREATE TABLE IF NOT EXISTS votes (
98	      id TEXT PRIMARY KEY,
99	      poll_id TEXT NOT NULL REFERENCES polls (id),
100	      option_id TEXT NOT NULL,
101	      nullifier TEXT NOT NULL,
102	      accepted_at TEXT NOT NULL
103	    );
104	    CREATE UNIQUE INDEX IF NOT EXISTS votes_poll_nullifier ON votes (poll_id, nullifier);
105	    CREATE TABLE IF NOT EXISTS group_versions (
106	      poll_id TEXT NOT NULL REFERENCES polls (id),
107	      version INTEGER NOT NULL,
108	      commitments_json TEXT NOT NULL,
109	      merkle_root TEXT NOT NULL,
110	      created_at TEXT NOT NULL,
111	      PRIMARY KEY (poll_id, version)
112	    );
113	    CREATE INDEX IF NOT EXISTS group_versions_root ON group_versions (poll_id, merkle_root);
114	    CREATE TABLE IF NOT EXISTS audit_events (
115	      id TEXT PRIMARY KEY,
116	      action TEXT NOT NULL,
117	      poll_id TEXT NOT NULL,
118	      result TEXT NOT NULL,
119	      at TEXT NOT NULL,
120	      details_json TEXT NOT NULL
121	    );
122	    CREATE INDEX IF NOT EXISTS audit_events_time ON audit_events (at DESC, id DESC);
123	  `);
124	  // Migrate pre-versioning databases: add the group columns to existing polls.
125	  const pollColumns = new Set((db.prepare("PRAGMA table_info(polls)").all() as { name: string }[]).map(column => column.name));
126	  if (!pollColumns.has("group_version")) db.exec("ALTER TABLE polls ADD COLUMN group_version INTEGER NOT NULL DEFAULT 1");
127	  if (!pollColumns.has("frozen_version")) db.exec("ALTER TABLE polls ADD COLUMN frozen_version INTEGER");
128	  if (!pollColumns.has("snapshot_json")) db.exec("ALTER TABLE polls ADD COLUMN snapshot_json TEXT");
129	
130	  const existing = db.prepare("SELECT count(*) AS count FROM polls").get() as { count: number };
131	  if (existing.count === 0) {
132	    const seed = JSON.parse(readFileSync(new URL("../fixtures/catalog.json", import.meta.url), "utf8")) as CatalogSeed;
133	    db.exec("BEGIN");
134	    try {
135	      const insertPoll = db.prepare("INSERT INTO polls (id, title, summary, description, organizer, status, published_at, closes_at, options_json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
136	      for (const poll of seed.polls) insertPoll.run(poll.id, poll.title, poll.summary, poll.description, poll.organizer, poll.status, poll.publishedAt, poll.closesAt, JSON.stringify(poll.options));
137	      const insertMember = db.prepare("INSERT INTO members VALUES (?, ?)");
138	      seed.memberCommitments.forEach((commitment, index) => insertMember.run(commitment, index));
139	      db.exec("COMMIT");
140	    } catch (error) { db.exec("ROLLBACK"); db.close(); throw error; }
141	  }
142	  // Legacy databases only ever knew the "open" state: normalize any poll whose
143	  // status is not part of the lifecycle to open, so old issues migrate forward.
144	  db.exec(`UPDATE polls SET status = 'open' WHERE status NOT IN ('draft', 'open', 'closed', 'archived')`);
