170	  // close audit event, to the last accepted vote, to the deadline. Written
171	  // once here, the snapshot is fixed from then on.
172	  const missingSnapshots = db.prepare("SELECT id FROM polls WHERE status IN ('closed', 'archived') AND snapshot_json IS NULL").all() as { id: string }[];
173	  if (missingSnapshots.length > 0) {
174	    db.exec("BEGIN");
175	    try {
176	      for (const { id } of missingSnapshots) {
177	        const closeAudit = (db.prepare("SELECT at, details_json FROM audit_events WHERE poll_id = ? AND action = 'poll_status_change' AND result = 'success' ORDER BY at ASC, id ASC").all(id) as { at: string; details_json: string }[])
