27	const list = document.querySelector<HTMLDivElement>("#poll-list")!;
28	const detail = document.querySelector<HTMLElement>("#poll-detail")!;
29	const tokenInput = document.querySelector<HTMLInputElement>("#admin-token")!;
30	const setButton = document.querySelector<HTMLButtonElement>("#admin-set")!;
31	const clearButton = document.querySelector<HTMLButtonElement>("#admin-clear")!;
32	const createButton = document.querySelector<HTMLButtonElement>("#admin-create")!;
33	const auditButton = document.querySelector<HTMLButtonElement>("#admin-audit")!;
34	const adminMode = document.querySelector<HTMLSpanElement>("#admin-mode")!;
