36	
37	function text(tag: string, content: string, className?: string): HTMLElement {
38	  const element = document.createElement(tag);
39	  element.textContent = content;
40	  if (className) element.className = className;
41	  return element;
42	}
43	function date(value: string) { return new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "long", day: "numeric", timeZone: "Asia/Shanghai" }).format(new Date(value)); }
44	function dateTime(value: string) { return new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false, timeZone: "Asia/Shanghai" }).format(new Date(value)); }
45	function isAdmin(): boolean { return adminToken.length > 0; }
46	
47	async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
48	  const headers = new Headers(init.headers);
49	  // Attach the in-memory token to every request while management mode is on.
50	  if (isAdmin()) headers.set("X-Admin-Token", adminToken);
51	  const response = await fetch(path, { ...init, headers });
52	  const body = await response.json().catch(() => undefined) as { error?: string } | undefined;
53	  if (!response.ok) throw Object.assign(new Error(`请求失败（${response.status}）`), { status: response.status, body });
54	  return body as T;
55	}
