69	  poll_not_found: "议题不存在",
70	  illegal_transition: "非法状态转换（仅允许 草稿→开放→截止→归档）",
71	  status_conflict: "状态已变化，expectedStatus 与当前状态冲突",
72	  invalid_status: "状态值非法",
73	  poll_exists: "议题 id 已存在",
