85	  return (code && ERROR_TEXT[code]) || (error instanceof Error ? error.message : "操作失败，请重试");
86	}
87	
88	function statusBadge(status: PollStatus): HTMLElement {
89	  return text("span", STATUS_LABEL[status], `status-badge status-${status}`);
90	}
91	
92	function resultsBlock(result: PollResults, poll: PollDetail): HTMLElement {
93	  const wrapper = text("div", "", "results");
94	  wrapper.append(text("h3", poll.status === "open" ? `当前结果 · 共 ${result.total} 票` : `最终结果 · 共 ${result.total} 票`));
95	  const labels = new Map(poll.options.map(option => [option.id, option.label]));
