105	
106	// ---- Management: lifecycle transition --------------------------------------
107	
108	function adminSection(poll: PollDetail): HTMLElement {
109	  const section = text("section", "", "admin-panel");
110	  section.append(text("h3", "议题管理"));
111	  const next = NEXT_STATUS[poll.status];
112	  const transition = document.createElement("button");
