119	    ? `合法转换：${STATUS_LABEL[poll.status]} → ${STATUS_LABEL[next]}（提交 expectedStatus=${poll.status}）`
120	    : "议题已归档，没有进一步的状态转换。";
121	  const statusLine = text("p", "", "admin-status-line");
