154	
155	  function row(operation: string, fields: [string, string][], label: string, build: (values: Record<string, string>) => Record<string, string>): HTMLElement {
156	    const form = document.createElement("div");
157	    form.className = "member-form";
158	    const inputs: Record<string, HTMLInputElement> = {};
159	    for (const [key, placeholder] of fields) {
