167	    const button = document.createElement("button");
168	    button.type = "button";
169	    button.className = "admin-button";
170	    button.textContent = label;
171	    const line = text("p", "", "member-form-status muted");
172	    button.addEventListener("click", async () => {
173	      const values = Object.fromEntries(Object.entries(inputs).map(([key, input]) => [key, input.value.trim()]));
174	      if (Object.values(values).some(value => !value)) { line.textContent = "请填写全部字段。"; line.className = "member-form-status error"; return; }
175	      button.disabled = true;
176	      try {
177	        const payload = { operation, expectedVersion: poll.groupVersion, ...build(values) };
178	        const { group } = await request<{ group: { version: number } }>(`/api/polls/${encodeURIComponent(poll.id)}/group`, {
179	          method: "POST",
180	          headers: { "Content-Type": "application/json" },
181	          body: JSON.stringify(payload)
182	        });
183	        line.textContent = `已生成新版本 v${group.version}。`;
184	        line.className = "member-form-status ok";
185	        await loadPolls();
186	        await showPoll(poll.id);
187	      } catch (error) {
188	        line.textContent = errorText(error);
189	        line.className = "member-form-status error";
190	        button.disabled = false;
191	      }
192	    });
193	    form.append(button, line);
194	    return form;
