196	
197	  box.append(
198	    row("join", [["commitment", "新成员承诺（十进制）"]], "追加成员", v => ({ commitment: v.commitment })),
199	    row("rotate", [["oldCommitment", "旧承诺"], ["newCommitment", "新承诺"]], "原位替换", v => ({ oldCommitment: v.oldCommitment, newCommitment: v.newCommitment })),
200	    row("revoke", [["commitment", "待移除承诺"]], "移除成员", v => ({ commitment: v.commitment }))
201	  );
