207	function voteSection(poll: PollDetail): HTMLElement {
208	  const section = text("section", "", "vote");
209	  section.append(text("h3", "匿名投票"));
210	  section.append(text("p", "身份秘密仅在本页内存中用于生成 Semaphore 零知识证明，不会上传、保存或离开浏览器。演示身份 veilvote-demo-member-01 至 veilvote-demo-member-08 仅供合成演示数据，不可用于真实用户。", "muted vote-note"));
211	
212	  const identityLabel = text("label", "身份秘密", "vote-label");
213	  const identityInput = document.createElement("input");
214	  identityInput.type = "password";
215	  identityInput.autocomplete = "off";
216	  identityInput.placeholder = "演示：veilvote-demo-member-01";
217	  identityLabel.append(identityInput);
218	
219	  const optionFieldset = document.createElement("fieldset");
220	  optionFieldset.className = "vote-options";
221	  optionFieldset.append(text("legend", "选择方案"));
222	  poll.options.forEach((option, index) => {
223	    const label = document.createElement("label");
224	    const radio = document.createElement("input");
225	    radio.type = "radio";
226	    radio.name = "vote-option";
227	    radio.value = option.id;
228	    if (index === 0) radio.checked = true;
229	    label.append(radio, text("span", option.label));
230	    optionFieldset.append(label);
231	  });
232	
233	  const submit = document.createElement("button");
234	  submit.type = "button";
235	  submit.className = "vote-submit";
236	  submit.textContent = "生成证明并提交选票";
237	  const status = text("p", "", "vote-status");
238	  status.setAttribute("aria-live", "polite");
239	  const receiptBox = text("div", "", "receipt");
240	  const resultsMount = text("div", "", "results-mount");
241	
242	  async function refreshResults() {
243	    try {
244	      const { result } = await request<{ result: PollResults }>(`/api/polls/${encodeURIComponent(poll.id)}/results`);
245	      resultsMount.replaceChildren(resultsBlock(result, poll));
246	    } catch (error) { resultsMount.replaceChildren(text("p", errorText(error), "error")); }
247	  }
248	
249	  let busy = false;
250	  submit.addEventListener("click", async () => {
251	    if (busy) return;
252	    const secret = identityInput.value.trim();
253	    const optionId = optionFieldset.querySelector<HTMLInputElement>("input:checked")?.value;
254	    if (!secret) { status.textContent = "请输入身份秘密。"; status.className = "vote-status error"; return; }
255	    if (!optionId) { status.textContent = "请选择一个方案。"; status.className = "vote-status error"; return; }
256	    busy = true;
257	    submit.disabled = true;
258	    receiptBox.replaceChildren();
259	    try {
260	      status.textContent = "正在生成身份与分组…";
261	      status.className = "vote-status";
262	      const [{ Identity }, { Group }, { generateProof }] = await Promise.all([
263	        import("@semaphore-protocol/identity"),
264	        import("@semaphore-protocol/group"),
265	        import("@semaphore-protocol/proof")
266	      ]);
267	      const identity = new Identity(secret);
268	      if (!poll.eligibleMemberCommitments.includes(identity.commitment.toString())) {
269	        throw new Error("该身份不在本议题的成员承诺中，请检查输入。");
270	      }
271	      const group = new Group(poll.eligibleMemberCommitments);
272	      status.textContent = "正在生成零知识证明（首次需下载证明参数）…";
273	      const proof = await generateProof(identity, group, optionId, poll.id);
274	      status.textContent = "正在提交选票…";
275	      const { receipt } = await request<{ receipt: VoteReceipt }>(`/api/polls/${encodeURIComponent(poll.id)}/votes`, {
276	        method: "POST",
277	        headers: { "Content-Type": "application/json" },
278	        body: JSON.stringify({ optionId, groupVersion: poll.groupVersion, proof })
279	      });
280	      identityInput.value = "";
281	      status.textContent = "投票已被接受，回执如下（可凭回执编号随时查询）。";
282	      status.className = "vote-status ok";
283	      const receiptList = document.createElement("dl");
284	      for (const [label, value] of [["回执编号", receipt.id], ["议题", receipt.pollId], ["选项", receipt.optionId], ["Nullifier", receipt.nullifier], ["接受时间", receipt.acceptedAt]]) {
285	        receiptList.append(text("dt", label), text("dd", value));
286	      }
287	      receiptBox.replaceChildren(receiptList);
288	      await refreshResults();
289	    } catch (error) {
290	      const code = (error as { body?: { error?: string } })?.body?.error;
291	      status.textContent = `${errorText(error)} 可修正后重试。`;
292	      status.className = "vote-status error";
293	      // The membership snapshot moved on: reload the detail so the next proof
294	      // is generated against the current version and root.
295	      if (code === "group_version_changed") setTimeout(() => void showPoll(poll.id), 1500);
296	    } finally {
297	      busy = false;
298	      submit.disabled = false;
299	    }
300	  });
301	
302	  const refresh = document.createElement("button");
303	  refresh.type = "button";
304	  refresh.className = "vote-refresh";
305	  refresh.textContent = "刷新结果";
306	  refresh.addEventListener("click", () => void refreshResults());
307	
308	  section.append(identityLabel, optionFieldset, submit, status, receiptBox, resultsMount, refresh);
309	  void refreshResults();
310	  return section;
311	}
