314	async function showPoll(id: string) {
315	  selected = id;
316	  list.querySelectorAll<HTMLButtonElement>("button").forEach(button => { button.classList.toggle("selected", button.dataset.id === id); button.setAttribute("aria-pressed", String(button.dataset.id === id)); });
317	  detail.replaceChildren(text("p", "正在读取议题…", "empty"));
318	  try {
319	    const { poll } = await request<{ poll: PollDetail }>(`/api/polls/${encodeURIComponent(id)}`);
320	    if (selected !== id) return;
321	    const heading = text("div", "", "detail-heading");
322	    heading.append(text("span", "公开议题", "tag"), statusBadge(poll.status), text("span", `发布于 ${date(poll.publishedAt)}`, "muted"));
323	    const stats = text("div", "", "stats");
324	    for (const [label, value] of [["参与成员", `${poll.memberCount} 位`], ["可选方案", `${poll.optionCount} 项`], ["成员版本", `v${poll.groupVersion}`], ["截止日期", date(poll.closesAt)]]) {
325	      const item = text("div", ""); item.append(text("span", label, "muted"), text("strong", value)); stats.append(item);
326	    }
327	    const options = document.createElement("ol"); options.className = "options";
328	    poll.options.forEach((option, index) => { const item = document.createElement("li"); item.append(text("span", String(index + 1).padStart(2, "0"), "option-number"), text("span", option.label)); options.append(item); });
329	    const commitments = document.createElement("details"); commitments.className = "commitments";
330	    commitments.append(text("summary", `成员公开承诺 · ${poll.eligibleMemberCommitments.length} 项 · 版本 v${poll.groupVersion}`));
331	    commitments.append(text("p", "承诺用于标识已登记的成员资格，不包含姓名或身份秘密。此处展示演示成员数据。", "muted"));
332	    const rootLine = text("p", "", "muted");
333	    rootLine.append(text("span", "当前快照 Merkle 根："), text("code", poll.merkleRoot));
334	    commitments.append(rootLine);
