336	
337	    detail.replaceChildren();
338	    detail.append(heading, text("h2", poll.title), text("p", poll.description, "description"), text("p", `议题组织方 / ${poll.organizer}`, "organizer"), stats, text("h3", "议题方案"), options, commitments);
339	    if (isAdmin()) detail.append(adminSection(poll));
340	    if (poll.status === "draft") {
341	      detail.append(text("p", "该议题仍为草稿：不对公众显示，普通详情、投票与结果均不可见。管理员可在上方完善成员名单后开放投票。", "draft-note"));
342	    } else if (poll.status === "open") {
343	      detail.append(voteSection(poll));
344	    } else {
345	      const mount = text("div", "", "results-mount");
346	      detail.append(text("p", poll.status === "closed" ? "议题已截止，结果如下并继续公开。" : "议题已归档，结果继续公开可查。", "muted"), mount);
347	      try {
348	        const { result } = await request<{ result: PollResults }>(`/api/polls/${encodeURIComponent(poll.id)}/results`);
349	        mount.replaceChildren(resultsBlock(result, poll));
350	      } catch (error) {
351	        mount.replaceChildren(text("p", errorText(error), "error"));
352	      }
353	    }
354	  } catch (error) { if (selected === id) detail.replaceChildren(text("p", error instanceof Error ? error.message : "暂时无法读取议题", "error")); }
355	}
