473	  body.className = "audit-body";
474	  body.append(text("p", "正在读取审计记录…", "muted"));
475	  openModal("审计记录（GET /api/admin/audit，按时间倒序）", body);
476	  try {
477	    const { events } = await request<{ events: AuditEvent[] }>("/api/admin/audit");
478	    body.replaceChildren();
479	    if (events.length === 0) { body.append(text("p", "暂无审计事件。")); return; }
480	    body.append(text("p", `共 ${events.length} 条；仅记录动作、议题、结果、时间与详情，不记录令牌、秘密或证明。`, "muted"));
481	    const table = document.createElement("table");
482	    table.className = "audit-table";
483	    table.append(htmlRow("thead", ["时间", "动作", "议题", "结果", "详情"]));
484	    const tbody = document.createElement("tbody");
485	    for (const event of events) {
486	      const tr = document.createElement("tr");
487	      tr.append(htmlCell("td", dateTime(event.at)));
488	      tr.append(htmlCell("td", ACTION_LABEL[event.action] ?? event.action));
489	      tr.append(htmlCell("td", event.pollId, "mono"));
490	      const resultCell = htmlCell("td", event.result === "success" ? "成功" : "失败");
491	      resultCell.className = event.result === "success" ? "ok mono" : "error mono";
492	      tr.append(resultCell);
493	      tr.append(htmlCell("td", JSON.stringify(event.details), "mono details"));
494	      tbody.append(tr);
495	    }
496	    table.append(tbody);
497	    body.append(table);
498	  } catch (error) {
499	    body.replaceChildren(text("p", errorText(error), "error"));
500	  }
501	}
502	function htmlRow(part: "thead", cells: string[]): HTMLElement {
503	  const thead = document.createElement(part);
504	  const tr = document.createElement("tr");
505	  for (const cell of cells) tr.append(htmlCell("th", cell));
506	  thead.append(tr);
507	  return thead;
508	}
509	function htmlCell(tag: "td" | "th", content: string, className = ""): HTMLElement {
510	  const cell = document.createElement(tag);
511	  cell.textContent = content;
512	  if (className) cell.className = className;
513	  return cell;
514	}
