.draft-note{margin-top:18px;padding:12px 14px;background:#f4efdd;border:1px solid #e0d6b2;border-radius:4px;color:#7c6f45;font-size:12px}
.modal-overlay{position:fixed;inset:0;background:rgba(25,45,37,.42);display:grid;place-items:center;z-index:50;padding:24px}
.modal{background:#fffef9;border:1px solid #dce2d2;border-radius:8px;max-width:820px;width:100%;max-height:86vh;overflow:auto;padding:24px 28px;box-shadow:0 18px 50px rgba(25,45,37,.25)}
.modal-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.modal-heading h3{margin:0;font-size:15px}
.create-form{display:flex;flex-direction:column;gap:11px}
.create-label{display:flex;flex-direction:column;gap:6px;font-size:11px;letter-spacing:1px;color:#7b8971}
.create-label input,.create-label textarea{font:inherit;font-size:13px;padding:9px 11px;border:1px solid #d5dbcb;border-radius:4px;background:#fbfbf6;color:#20372f}
.create-label input:focus-visible,.create-label textarea:focus-visible{outline:2px solid #94b184;outline-offset:1px}
.option-rows{display:flex;flex-direction:column;gap:8px}
.option-row{display:flex;gap:8px}
.option-row input{font:inherit;font-size:12px;padding:8px 10px;border:1px solid #d5dbcb;border-radius:4px;background:#fbfbf6}
.option-row input:first-child{width:200px}
.option-row input:nth-child(2){flex:1}
.create-status{font-size:12px;margin:4px 0 0}
.create-status.ok{color:#4c7050}
.create-status.error{color:#a14435}
.audit-body{font-size:12px}
.audit-table{width:100%;border-collapse:collapse;font-size:11px;margin-top:10px}
.audit-table th{text-align:left;font-weight:600;letter-spacing:1px;color:#7b8971;padding:7px 9px;border-bottom:1px solid #dfe3d5}
.audit-table td{padding:8px 9px;border-bottom:1px solid #eef0e7;vertical-align:top}
.audit-table .mono{font-family:ui-monospace,monospace;font-size:10px}
