import type { AuditPage, PollSnapshot, VoteReceipt } from "../src/types.ts";

const ADMIN_TOKEN = "frontend-test-token";
const adminHeaders = { "Content-Type": "application/json", "X-Admin-Token": ADMIN_TOKEN };

// Bundle the real frontend once for the whole file. CSS is stubbed; the
// Semaphore packages are external (the tests below never cast a vote, so the
// lazy proof-generation imports never resolve).
const buildDirectory = mkdtempSync(join(tmpdir(), "veilvote-frontend-build-"));
