}
const click = (element: Element) => (element as HTMLElement).dispatchEvent(new windowish.Event("click", { bubbles: true, cancelable: true }));
const change = (element: Element) => element.dispatchEvent(new windowish.Event("change", { bubbles: true }));
// Event constructor must come from the active jsdom window of the most recent
// mount; the sequential tests below only use it while a page is mounted.
