    // Network failure (fetch rejects with a TypeError).
    page.setFetchOverride(async () => { throw new TypeError("Failed to fetch"); });
    submit();
    await waitFor(() => statusLine().textContent!.includes("网络失败"));
    assert.equal(allInputs().every(i => !i.disabled), true, "form is editable again for retry");

    // Pending submission disables the form and ignores a second submit.
    let release: () => void = () => {};
    let calls = 0;
    page.setFetchOverride(() => {
      calls += 1;
      return new Promise<Response>(resolve => {
        release = () => resolve(new Response(JSON.stringify({ valid: true, receipt: started.receipts[0] }), { status: 200, headers: { "Content-Type": "application/json" } }));
      });
    });
    submit();
    await waitFor(() => submitButton().disabled === true);
    assert.ok(allInputs().every(i => i.disabled), "every input is disabled while pending");
    submit();
    assert.equal(calls, 1, "a repeated submit while pending does not fire another request");
    release();
    await waitFor(() => statusLine().textContent!.includes("核验成功"));
    assert.equal(submitButton().disabled, false);

    // After restoring the real network, a corrected retry succeeds.
    page.setFetchOverride(null);
    input("#verify-receipt-id").value = started.receipts[1].id;
    input("#verify-option-id").value = started.receipts[1].optionId;
    input("#verify-nullifier").value = started.receipts[1].nullifier;
    submit();
    await waitFor(() => statusLine().textContent!.includes("核验成功"));
  } finally {
    page.cleanup();
    await stop(started.server);
    rmSync(directory, { recursive: true, force: true });
  }
});

test("frontend: audit view loads, filters reset to page 1, pages, and handles empty/401/400/out-of-range", async () => {
  const directory = mkdtempSync(join(tmpdir(), "veilvote-fe-audit-"));
  const databasePath = join(directory, "veilvote.sqlite");
  const { server, base } = await serve(databasePath);
  const page = await mountPage(base);
  try {
    await waitFor(() => page.document.querySelectorAll(".poll-card").length === 2);
    // 12 successful creates + 2 failed transitions => >=14 events, 2 pages at 10.
    for (let i = 1; i <= 12; i += 1) {
      const id = `evt-${String(i).padStart(2, "0")}`;
      const result = await jsonFetch(base, "/api/polls", { method: "POST", body: JSON.stringify(votedPollPayload(id)) });
      assert.equal(result.status, 201);
    }
    for (let i = 0; i < 2; i += 1) {
      await jsonFetch(base, "/api/polls/evt-01/status", {
        method: "POST", body: JSON.stringify({ status: "closed", expectedStatus: "draft" })
      });
    }
    await setAdminToken(page, ADMIN_TOKEN);
    const openAudit = () => page.document.querySelector<HTMLButtonElement>("#admin-audit")!.click();
    const state = () => page.document.querySelector(".audit-state")!;
    const rowCount = () => page.document.querySelectorAll(".audit-table tbody tr").length;
    openAudit();
    await waitFor(() => /共 14 条/.test(page.document.querySelector(".audit-summary")?.textContent ?? ""));
    assert.match(page.document.querySelector("#audit-page-indicator")!.textContent!, /第 1 \/ 2 页/);
    assert.equal(rowCount(), 10);

    // Move to page 2, then change a filter: the request must return to page 1.
    page.document.querySelector<HTMLButtonElement>("#audit-next")!.click();
    await waitFor(() => /第 2 \/ 2 页/.test(page.document.querySelector("#audit-page-indicator")!.textContent!));
    assert.equal(rowCount(), 4);
    const resultFilter = page.document.querySelector<HTMLSelectElement>("#audit-filter-result")!;
    resultFilter.value = "failure";
    change(resultFilter);
    await waitFor(() => rowCount() === 2);
    const lastUrl = page.fetchSpy.auditUrls.at(-1)!;
    assert.match(lastUrl, /page=1(?!\d)/, "filter change resets to page 1");
    assert.match(lastUrl, /result=failure/);
    assert.ok([...page.document.querySelectorAll(".audit-table tbody tr")].every(tr => /失败/.test(tr.children[3].textContent!)));

    // Exact pollId filter.
    resultFilter.value = "";
    change(resultFilter);
    await waitFor(() => /共 14 条/.test(page.document.querySelector(".audit-summary")?.textContent ?? ""));
    const pollFilter = page.document.querySelector<HTMLInputElement>("#audit-filter-poll-id")!;
    pollFilter.value = "evt-01";
    change(pollFilter);
    await waitFor(() => /共 3 条/.test(page.document.querySelector(".audit-summary")?.textContent ?? ""));
    assert.ok([...page.document.querySelectorAll(".audit-table tbody tr")].every(tr => tr.children[2].textContent === "evt-01"));

    // Empty result set.
    pollFilter.value = "no-such-poll";
    change(pollFilter);
    await waitFor(() => state().textContent!.includes("没有符合"));
    assert.equal(rowCount(), 0);

    // 401 with a wrong token.
    pollFilter.value = "";
    change(pollFilter);
    page.document.querySelector<HTMLButtonElement>("#admin-clear")!.click();
    await waitFor(() => page.document.querySelector("#admin-audit") === null || (page.document.querySelector<HTMLButtonElement>("#admin-audit")?.hidden === true));
    await setAdminToken(page, "wrong-token");
    openAudit();
    await waitFor(() => state().textContent!.includes("401"));
    assert.match(state().textContent!, /admin_unauthorized|未授权/);
    page.document.querySelector("#admin-clear")!.click();
    await setAdminToken(page, ADMIN_TOKEN);

    // 400 from the server is shown via the fetch override.
    page.setFetchOverride(async () => new Response(JSON.stringify({ error: "invalid_time_range" }), { status: 400, headers: { "Content-Type": "application/json" } }));
    openAudit();
    await waitFor(() => state().textContent!.includes("400"));
    assert.match(state().textContent!, /时间范围/);
    page.setFetchOverride(null);

    // Out-of-range page returns an empty page without crashing and offers a way back.
    let rewriteOutOfRange = true;
    page.setFetchOverride((input, init) => {
      const url = String(input);
      const rewritten = rewriteOutOfRange ? url.replace(/page=\d+/, "page=99") : url;
      return fetch(rewritten, init);
    });
    openAudit();
    await waitFor(() => state().textContent!.includes("超出范围"));
    assert.equal(rowCount(), 0);
    assert.match(page.document.querySelector("#audit-page-indicator")!.textContent!, /第 99 \/ 2 页/);
    assert.equal(page.document.querySelector<HTMLButtonElement>("#audit-first")!.disabled, false);
    rewriteOutOfRange = false;
    page.document.querySelector<HTMLButtonElement>("#audit-first")!.click();
    await waitFor(() => rowCount() === 10);
    page.setFetchOverride(null);

    // First/last pager buttons hit the expected page numbers.
    openAudit();
    await waitFor(() => /共 14 条/.test(page.document.querySelector(".audit-summary")?.textContent ?? ""));
    page.document.querySelector<HTMLButtonElement>("#audit-last")!.click();
    await waitFor(() => /第 2 \/ 2 页/.test(page.document.querySelector("#audit-page-indicator")!.textContent!));
    assert.match(page.fetchSpy.auditUrls.at(-1)!, /page=2(?!\d)/);
  } finally {
    page.cleanup();
    await stop(server);
    rmSync(directory, { recursive: true, force: true });
  }
});

