60	    url: "http://veilvote.test/", pretendToBeVisual: true
61	  });
62	  const window = dom.window;
63	  const clipboard = { value: "" };
64	  Object.defineProperty(window.navigator, "clipboard", {
65	    configurable: true,
66	    value: { writeText: async (value: string) => { clipboard.value = value; } }
67	  });
68	  const globalNames = ["window", "document", "navigator", "HTMLElement", "HTMLInputElement", "HTMLSelectElement",
69	    "HTMLFormElement", "HTMLButtonElement", "Element", "Node", "NodeList", "Document", "DocumentFragment",
70	    "Event", "MouseEvent", "Option", "FormData", "customElements", "getComputedStyle", "fetch"];
71	  const saved: Record<string, PropertyDescriptor | undefined> = {};
72	  for (const name of globalNames) saved[name] = Object.getOwnPropertyDescriptor(globalThis, name);
73	
74	  const fetchSpy = { auditUrls: [] as string[], calls: 0 };
75	  const realFetch = globalThis.fetch.bind(globalThis);
76	  let override: FetchOverride | null = null;
77	  const routingFetch = (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
78	    fetchSpy.calls += 1;
79	    const href = typeof input === "string" && input.startsWith("/") ? `${base}${input}` : input;
80	    if (typeof href === "string" && href.includes("/api/admin/audit")) {
81	      fetchSpy.auditUrls.push(href.slice(href.indexOf("/api/admin/audit")));
82	    }
83	    if (override) return override(href as RequestInfo | URL, init, realFetch);
84	    return realFetch(href as RequestInfo | URL, init);
85	  };
86	
87	  for (const name of ["window", "document", "HTMLElement", "HTMLInputElement", "HTMLSelectElement",
88	    "HTMLFormElement", "HTMLButtonElement", "Element", "Node", "NodeList", "Document", "DocumentFragment",
89	    "Event", "MouseEvent", "Option", "FormData", "customElements"]) {
90	    Object.defineProperty(globalThis, name, { value: window[name], configurable: true, writable: true });
91	  }
92	  Object.defineProperty(globalThis, "getComputedStyle", { value: window.getComputedStyle.bind(window), configurable: true, writable: true });
93	  Object.defineProperty(globalThis, "navigator", { value: window.navigator, configurable: true, writable: true });
94	  Object.defineProperty(globalThis, "fetch", { value: routingFetch, configurable: true, writable: true });
95	
96	  await import(pathToFileURL(bundlePath).href + `?page=${++pageSerial}`);
97	
98	  return {
