18	async function serve(): Promise<{ server: Server; base: string }> {
19	  const server = createApp(databasePath, undefined, { adminToken: ADMIN_TOKEN });
20	  await new Promise<void>((done, reject) => { server.once("error", reject); server.listen(0, "127.0.0.1", done); });
21	  const address = server.address();
22	  if (!address || typeof address === "string") throw new Error("Service has no TCP address");
23	  return { server, base: `http://127.0.0.1:${address.port}` };
24	}
25	async function stop(server: Server) {
26	  server.closeAllConnections();
27	  await new Promise<void>((done, reject) => server.close(error => error ? reject(error) : done()));
28	}
29	async function pollDetail(base: string, pollId: string, token?: string) {
30	  const response = await fetch(`${base}/api/polls/${encodeURIComponent(pollId)}`, token ? { headers: { "X-Admin-Token": token } } : undefined);
31	  if (!response.ok) throw new Error(`Poll detail returned ${response.status}`);
32	  return ((await response.json()) as { poll: PollDetail }).poll;
