34	async function api(base: string, path: string, init: RequestInit & { token?: string | false } = {}) {
35	  const headers = new Headers(init.headers);
36	  if (init.token !== false) headers.set("X-Admin-Token", init.token ?? ADMIN_TOKEN);
37	  if (init.body && !headers.has("Content-Type")) headers.set("Content-Type", "application/json");
38	  const response = await fetch(`${base}${path}`, { ...init, headers });
39	  return { status: response.status, body: await response.json().catch(() => ({})) as Record<string, unknown> };
