46	function digestOf(snapshot: PollSnapshot): string {
47	  const { pollId, groupVersion, total, options, closedAt } = snapshot;
48	  return createHash("sha256").update(JSON.stringify({ pollId, groupVersion, total, options, closedAt }), "utf8").digest("hex");
49	}
